				Validate(func(s []string) error {
					if len(s) == 0 {
						return errors.New("select at least one repo")
					}
					return nil
				}).
				Value(&selected),
		),
	)
	if err := form.RunWithContext(ctx); err != nil {
		return nil, handleFormCancellation(w, "Mirror create", err)
