// Package onboarding models the setup ladder shared by `entire enable` and
// `entire status`: an ordered list of rungs (hooks, auth, mirror, import),
// each recomputing done/missing from ground truth — or a short-TTL cache of
// it, for network probes — on every check. Keeping the
// model in one place guarantees enable's prompts, its closing summary, and
// status's checklist can never disagree about what is connected.
package onboarding

import (
	"context"
	"sync"
)

// Rung keys — stable identifiers shared by the ladder, enable's offer map,
// the status renderer, and the `status --json` setup object.
const (
	KeyHooks  = "hooks"
	KeyAuth   = "auth"
	KeyMirror = "mirror"
	KeyImport = "import"
)

// State classifies a rung's ground-truth check result.
type State int

const (
	// StateUnknown means the check could not run (e.g. offline mirror probe).
	StateUnknown State = iota
	// StateDone means the rung is satisfied.
	StateDone
	// StateMissing means the rung is actionable now.
	StateMissing
	// StateBlocked means the rung cannot be fixed by an offer right now:
	// a prerequisite rung is missing (e.g. mirror needs login), or recovery
	// is out of the user's hands (e.g. an admin-suspended mirror).
	StateBlocked
	// StateNotApplicable means the rung does not apply here (e.g. non-GitHub origin).
	StateNotApplicable
)

// String returns the stable machine-readable name used in `status --json`.
func (s State) String() string {
	switch s {
	case StateDone:
		return "done"
	case StateMissing:
		return "missing"
	case StateBlocked:
		return "blocked"
	case StateNotApplicable:
		return "not_applicable"
	case StateUnknown:
		return "unknown"
	}
	return "unknown"
}

// Check is the outcome of one rung's status probe.
type Check struct {
	State State
	// Detail is a short human fragment for checklist rows, e.g. a login handle
	// or "12 sessions found, not imported".
	Detail string
	// Hint is the exact command to run later when the rung is skipped/missing
	// (e.g. "entire auth login"), or the retry/diagnose command when the
	// check couldn't run (rendered as "couldn't check — retry with ...").
	Hint string
}

// Rung is one step of the setup ladder, defined as data rather than an
// interface so ladders stay trivially composable and testable.
type Rung struct {
	Key   string
	Title string
	// Check recomputes the rung's state from ground truth. It must not prompt.
	// Offers (the interactive setup steps) are wired separately in the enable
	// runner's offer map, keyed by Rung.Key.
	Check func(ctx context.Context) Check
}

// Ladder is an ordered set of rungs.
type Ladder []Rung

// Result pairs a rung with its check outcome.
type Result struct {
	Rung  Rung
	Check Check
}

// Checks runs every rung's Check concurrently and returns results in ladder
// order. Concurrency keeps hot paths (`entire status`) at the latency of the
// slowest single probe instead of the sum; rung checks are independent,
// read-only ground-truth reads.
func (l Ladder) Checks(ctx context.Context) []Result {
	results := make([]Result, len(l))
	var wg sync.WaitGroup
	for i, r := range l {
		wg.Add(1)
		go func() {
			defer wg.Done()
			results[i] = Result{Rung: r, Check: r.Check(ctx)}
		}()
	}
	wg.Wait()
	return results
}

// Summary returns how many applicable rungs are done and how many apply at
// all. NotApplicable rungs are excluded from both counts.
func Summary(results []Result) (done, total int) {
	for _, r := range results {
		if r.Check.State == StateNotApplicable {
			continue
		}
		total++
		if r.Check.State == StateDone {
			done++
		}
	}
	return done, total
}

// Complete reports whether every applicable rung is done.
func Complete(results []Result) bool {
	done, total := Summary(results)
	return done == total
}

// Missing returns the rungs that still need action, in ladder order. Blocked
// rungs are included (they become actionable once prerequisites are met);
// Unknown rungs are not, since an unreachable check proves nothing.
func Missing(results []Result) []Result {
	var missing []Result
	for _, r := range results {
		if r.Check.State == StateMissing || r.Check.State == StateBlocked {
			missing = append(missing, r)
		}
	}
	return missing
}

package cli

import (
	"context"
	"fmt"
	"net/url"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/onboarding"
)

// onboardingStatusResults computes the setup-ladder results for `entire
// status`. Package-level seam so status tests can stub ladder state without
// keyring/network access.
var onboardingStatusResults = func(ctx context.Context) []onboarding.Result {
	return onboardingLadder(newOnboardingRungDeps()).Checks(ctx)
}

// renderOnboardingChecklist renders the setup ladder for `entire status` and
// enable's closing summary. Fully connected collapses to a single line so the
// steady state stays quiet; anything less renders one row per applicable rung
// plus, when actionable steps remain, a pointer back at `entire enable`,
// which re-offers whatever is missing.
func renderOnboardingChecklist(results []onboarding.Result, sty statusStyles) string {
	if onboarding.Complete(results) {
		return renderConnectedLine(results, sty)
	}

	// When login is the ONLY remaining step, this is a reconnect (a deliberate
	// logout, or a never-logged-in local repo), not unfinished onboarding — so
	// drop the "Setup X/Y … finish setup → entire enable" framing and point
	// straight at the login command. auth is the sole actionable rung only when
	// nothing else needs enable: mirror/import are done or not applicable (e.g.
	// a repo with no GitHub origin has no web-UI payoff to "finish"). A
	// mirrorable repo that's logged out still has a blocked mirror rung, so it
	// keeps the full setup framing.
	missing := onboarding.Missing(results)
	reconnectOnly := len(missing) == 1 && missing[0].Rung.Key == onboarding.KeyAuth

	var b strings.Builder
	if !reconnectOnly {
		done, total := onboarding.Summary(results)
		b.WriteString(sty.render(sty.bold, fmt.Sprintf("Setup %d/%d complete", done, total)))
		b.WriteString("\n")
	}

	titleWidth := 0
	for _, r := range results {
		if r.Check.State != onboarding.StateNotApplicable && len(r.Rung.Title) > titleWidth {
			titleWidth = len(r.Rung.Title)
		}
	}
	for _, r := range results {
		if r.Check.State == onboarding.StateNotApplicable {
			continue
		}
		b.WriteString("  ")
		b.WriteString(onboardingRowMarker(r.Check.State, sty))
		b.WriteString(" ")
		fmt.Fprintf(&b, "%-*s", titleWidth, r.Rung.Title)
		detail := r.Check.Detail
		// An unknown rung (e.g. offline mirror probe) doesn't count as a
		// missing step, so its hint would otherwise never surface — carry it
		// in the row instead of leaving a bare "?" with nothing actionable.
		if detail == "" && r.Check.State == onboarding.StateUnknown && r.Check.Hint != "" {
			detail = "couldn't check — retry with `" + r.Check.Hint + "`"
		}
		if detail != "" {
			b.WriteString("  ")
			b.WriteString(sty.render(sty.dim, detail))
		}
		b.WriteString("\n")
	}

	if reconnectOnly {
		hint := missing[0].Check.Hint
		if hint == "" {
			hint = authLoginCommand
		}
		b.WriteString(sty.render(sty.cyan, fmt.Sprintf("→ Run `%s` to connect", hint)))
		b.WriteString("\n")
	} else if remaining := len(missing); remaining > 0 {
		step := "steps"
		if remaining == 1 {
			step = "step"
		}
		b.WriteString(sty.render(sty.cyan,
			fmt.Sprintf("→ Run `entire enable` to finish setup (%d %s left)", remaining, step)))
		b.WriteString("\n")
	}
	return b.String()
}

func onboardingRowMarker(state onboarding.State, sty statusStyles) string {
	switch state {
	case onboarding.StateDone:
		return sty.render(sty.green, "✓")
	case onboarding.StateMissing, onboarding.StateBlocked:
		return sty.render(sty.red, "✗")
	case onboarding.StateUnknown, onboarding.StateNotApplicable:
		return sty.render(sty.dim, "?")
	}
	return "?"
}

// renderConnectedLine is the fully-connected collapse: identity plus, when a
// mirror exists, the repo's entire.io overview link — the payoff the setup
// was for, e.g. "Connected: peyton · https://entire.io/gh/o/r".
func renderConnectedLine(results []onboarding.Result, sty statusStyles) string {
	var identity, mirror string
	for _, r := range results {
		switch r.Rung.Key {
		case onboarding.KeyAuth:
			identity = r.Check.Detail
		case onboarding.KeyMirror:
			if r.Check.State == onboarding.StateDone {
				mirror = r.Check.Detail
			}
		}
	}
	line := "Connected"
	if identity != "" {
		line += ": " + identity
	}
	if mirror != "" {
		if u := repoWebURL(mirror); u != "" {
			line += sty.render(sty.dim, " · ") + sty.render(sty.cyan, u)
		} else {
			line += sty.render(sty.dim, " · ") + "mirrored to " + mirror
		}
	}
	return line + "\n"
}

// repoWebURL builds the entire.io overview page for a mirrored GitHub repo
// from the checklist's "github.com/owner/repo" detail; "" when the detail
// isn't that shape.
func repoWebURL(mirrorSlug string) string {
	rest, ok := strings.CutPrefix(mirrorSlug, "github.com/")
	if !ok {
		return ""
	}
	owner, repo, ok := strings.Cut(rest, "/")
	if !ok || owner == "" || repo == "" {
		return ""
	}
	return fmt.Sprintf("%s/gh/%s/%s", webBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
}

package cli

import (
	"context"
	"fmt"
	"io"
	"strings"

	"charm.land/huh/v2"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/onboarding"
)

// onboardingSetupMode is the answer to enable's single consent prompt.
type onboardingSetupMode int

const (
	// setupModeSkip declines the offers this once — tracking continues either
	// way; the closing checklist carries the run-later commands and re-running
	// enable re-offers whatever is still missing. Deliberately the zero value:
	// a forgotten or defaulted mode must never run login or mirror creation.
	setupModeSkip onboardingSetupMode = iota
	// setupModeAll runs every missing rung back-to-back without further questions.
	setupModeAll
	// setupModeStepByStep confirms each missing rung individually.
	setupModeStepByStep
)

// onboardingOfferRunner drives the connect rungs at the end of `entire
// enable`: one consent prompt, then offers for whatever is missing, then the
// closing checklist. Rung state is recomputed before each offer, so a login
// completed in this pass unblocks the mirror rung in the same pass, and a
// rung finished out-of-band is never re-offered — which is also what makes
// re-running `entire enable` the resume path after an interrupted setup.
// All fields are seams; newOnboardingOfferRunner wires production behavior.
type onboardingOfferRunner struct {
	deps onboardingRungDeps
	// offerFns runs a rung's setup step; granular=true (step-by-step mode)
	// lets an offer present its own finer-grained picker.
	offerFns map[string]func(ctx context.Context, granular bool) error
	// selfPrompting marks offers that present their own confirmation UI in
	// granular mode (the import picker), so runOffers skips the generic
	// yes/no confirm instead of asking twice.
	selfPrompting map[string]bool
	// autoRun marks rungs whose offer runs without a prompt when prompting is
	// unavailable — --yes ("accept all defaults") auto-imports, matching the
	// enable-time import contract; login/mirror are never implicit.
	autoRun     map[string]bool
	canPrompt   func() bool
	promptMode  func(ctx context.Context, missing []onboarding.Result) (onboardingSetupMode, error)
	confirmRung func(ctx context.Context, r onboarding.Result) (bool, error)
	styles      func(w io.Writer) statusStyles
}

func (r onboardingOfferRunner) run(ctx context.Context, w io.Writer) {
	ladder := onboardingLadder(r.deps)
	results := ladder.Checks(ctx)

	if actionable := r.offerable(results); len(actionable) > 0 && r.canPrompt() {
		mode, err := r.promptMode(ctx, actionable)
		if err != nil {
			// Cancelling the consent prompt (Ctrl-C) behaves like skip: enable
			// has already succeeded, so fall through to the checklist, whose
			// hints are the resume path. Logged so a broken terminal doesn't
			// masquerade as a user choice.
			logging.Debug(ctx, "onboarding: consent prompt did not complete", "error", err)
			mode = setupModeSkip
		}
		if mode != setupModeSkip {
			r.runOffers(ctx, w, ladder, mode)
			results = ladder.Checks(ctx)
		}
	} else if r.runAutoOffers(ctx, w, ladder) {
		results = ladder.Checks(ctx)
	}

	fmt.Fprint(w, r.renderChecklist(w, results))
}

// runAutoOffers runs the autoRun rungs' offers when the prompt path didn't
// execute (no TTY or --yes). Reports whether any offer ran.
func (r onboardingOfferRunner) runAutoOffers(ctx context.Context, w io.Writer, ladder onboarding.Ladder) bool {
	ran := false
	for _, rung := range ladder {
		offer := r.offerFns[rung.Key]
		if offer == nil || !r.autoRun[rung.Key] {
			continue
		}
		if rung.Check(ctx).State != onboarding.StateMissing {
			continue
		}
		ran = true
		if err := offer(ctx, false); err != nil {
			logging.Warn(ctx, "onboarding: auto offer failed", "rung", rung.Key, "error", err)
			fmt.Fprintf(w, "  %s setup didn't complete: %v\n", rung.Title, err)
		}
	}
	return ran
}

// offerable filters the remaining work down to rungs this runner can act on.
// Missing rungs with an offer always qualify. Blocked rungs qualify only when
// an offerable Missing rung precedes them in the ladder — an earlier offer in
// the same pass (login) can unblock them. Without that, the consent prompt
// would promise work that can never run (e.g. auth Unknown leaves mirror
// Blocked with nothing to unblock it).
func (r onboardingOfferRunner) offerable(results []onboarding.Result) []onboarding.Result {
	var actionable []onboarding.Result
	unblockPossible := false
	for _, res := range results {
		if res.Check.State == onboarding.StateMissing && r.offerFns[res.Rung.Key] != nil {
			actionable = append(actionable, res)
			unblockPossible = true
			continue
		}
		if res.Check.State == onboarding.StateBlocked && r.offerFns[res.Rung.Key] != nil && unblockPossible {
			actionable = append(actionable, res)
		}
	}
	return actionable
}

// runOffers walks the ladder in order, re-checking each rung immediately
// before its offer. Offers are best-effort: a failure prints a notice and
// the closing checklist keeps the retry hint, but enable never fails.
func (r onboardingOfferRunner) runOffers(ctx context.Context, w io.Writer, ladder onboarding.Ladder, mode onboardingSetupMode) {
	granular := mode == setupModeStepByStep
	for _, rung := range ladder {
		offer := r.offerFns[rung.Key]
		if offer == nil {
			continue
		}
		check := rung.Check(ctx)
		if check.State != onboarding.StateMissing {
			continue
		}
		if granular && !r.selfPrompting[rung.Key] {
			accepted, err := r.confirmRung(ctx, onboarding.Result{Rung: rung, Check: check})
			if err != nil {
				// A failed confirm (Ctrl-C, broken terminal, cancelled ctx)
				// means the user is bailing out — stop walking rungs instead
				// of surfacing every remaining prompt one Ctrl-C at a time.
				logging.Debug(ctx, "onboarding: rung confirm prompt did not complete; stopping offers", "rung", rung.Key, "error", err)
				return
			}
			if !accepted {
				continue
			}
		}
		if err := offer(ctx, granular); err != nil {
			logging.Warn(ctx, "onboarding: offer failed", "rung", rung.Key, "error", err)
			fmt.Fprintf(w, "  %s setup didn't complete: %v\n", rung.Title, err)
		}
	}
}

func (r onboardingOfferRunner) renderChecklist(w io.Writer, results []onboarding.Result) string {
	sty := r.styles(w)
	var b strings.Builder
	b.WriteString(renderOnboardingChecklist(results, sty))
	// One "run later" line per unique command, in ladder order — a blocked
	// rung whose fix is another rung's command (mirror needs login) must not
	// repeat it.
	seen := map[string]bool{}
	for _, res := range onboarding.Missing(results) {
		if res.Check.Hint == "" || seen[res.Check.Hint] {
			continue
		}
		seen[res.Check.Hint] = true
		fmt.Fprintf(&b, "  run later: %s\n", sty.render(sty.cyan, res.Check.Hint))
	}
	return b.String()
}

// enableOnboardingOpts carries the enable-path context the ladder needs.
type enableOnboardingOpts struct {
	// assumeYes: --yes, "accept all defaults" — suppresses prompts.
	assumeYes bool
	// neverPrompt: the --agent path's documented non-interactive contract —
	// suppresses prompts without auto-running anything.
	neverPrompt bool
	// firstRun gates --yes auto-import: on the very first enable, --yes
	// auto-imports (the enable-time import contract); on any later enable it
	// must not, because "unimported history exists" cannot distinguish "new
	// history" from "history the user explicitly declined to import".
	// Interactive re-enables still offer — consent is explicit there.
	firstRun bool
	// importScope narrows the import offer to specific agents (the
	// just-selected ones, or the --agent target). Nil means every agent
