type configureUpstreamField struct {
	*huh.Select[string]
	cursor int
	count  int
}

func (field *configureUpstreamField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
		switch {
		case configureUpKey(keyMsg.String()):
			if field.cursor > 0 {
				field.cursor--
			}
		case configureDownKey(keyMsg.String()):
			if field.cursor == field.count-1 {
				return field, huh.NextField
			}
			field.cursor++
		}
	}
	model, cmd := field.Select.Update(msg)
	field.Select = model.(*huh.Select[string])
	return field, cmd
}

type configureAgentField struct {
	*huh.MultiSelect[string]
	cursor int
	count  int
}

func (field *configureAgentField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
		switch {
		case configureUpKey(keyMsg.String()):
			if field.cursor == 0 {
				return field, huh.PrevField
			}
			field.cursor--
		case configureDownKey(keyMsg.String()):
			field.cursor++
			if field.cursor >= field.count {
				field.cursor = 0
			}
		}
	}
	model, cmd := field.MultiSelect.Update(msg)
	field.MultiSelect = model.(*huh.MultiSelect[string])
	return field, cmd
}

func configureUpKey(key string) bool {
	switch key {
	case "up", "k", "ctrl+k", "ctrl+p":
		return true
	default:
		return false
	}
}

func configureDownKey(key string) bool {
	switch key {
	case "down", "j", "ctrl+j", "ctrl+n":
		return true
	default:
		return false
	}
}

