func (field *configureUpstreamField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
		switch {
		case configureNextKey(keyMsg.String()):
			// The wrapped huh.Select cannot reliably infer its field position
			// through the decorator, so emit the transition explicitly. Arrow
			// navigation has already kept the accessor's value up to date.
			return field, huh.NextField
		case configureUpKey(keyMsg.String()):
			if field.cursor > 0 {
				field.cursor--
			}
		case configureDownKey(keyMsg.String()):
			if field.cursor == field.count-1 {
				return field, huh.NextField
			}
			field.cursor++
		}
	}
	model, cmd := field.Select.Update(msg)
	if updated, ok := model.(*huh.Select[string]); ok {
		field.Select = updated
	}
	return field, cmd
}

type configureAgentField struct {
	*huh.MultiSelect[string]

	cursor int
	count  int
}

func (field *configureAgentField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
		switch {
		case configureUpKey(keyMsg.String()):
			if field.cursor == 0 {
				return field, huh.PrevField
			}
			field.cursor--
		case configureDownKey(keyMsg.String()):
			field.cursor++
			if field.cursor >= field.count {
				field.cursor = 0
			}
		}
	}
	model, cmd := field.MultiSelect.Update(msg)
	if updated, ok := model.(*huh.MultiSelect[string]); ok {
		field.MultiSelect = updated
	}
	return field, cmd
}

