		theme.Focused.Base = lipgloss.NewStyle()
		theme.Blurred.Base = lipgloss.NewStyle()
		theme.Focused.SelectSelector = lipgloss.NewStyle().Foreground(success).SetString("● ")
		theme.Blurred.SelectSelector = lipgloss.NewStyle().Foreground(success).SetString("● ")

